import re, pathlib

D = pathlib.Path("crates/callisto-model/src/release")
MODS = ["package_id", "github", "digest", "decision", "snapshot", "operation", "artifact", "intent", "execution", "report"]
text = {m: (D / f"{m}.rs").read_text() for m in MODS}

ITEM = re.compile(r"^(pub(?:\([a-z]+\))? )?(?:struct|enum|fn|const|type)\s+([A-Za-z_0-9]+)", re.M)
MACRO = re.compile(r"^release_digest!\(\s*([A-Za-z0-9_]+)", re.M)
defs = {}  # name -> (module, is_pub)
for m, t in text.items():
    for mt in ITEM.finditer(t):
        defs[mt.group(2)] = (m, bool(mt.group(1)))
    for mt in MACRO.finditer(t):
        defs[mt.group(1)] = (m, True)
# facade-owned items
defs["version_ord_key"] = ("", False)
defs["check_schema_version"] = ("", True)

def uses(body, ident):
    return re.search(rf"\b{re.escape(ident)}\b", body) is not None

def strip_comments(t):
    return "\n".join(l for l in t.split("\n") if not l.lstrip().startswith("//"))

EXT = [
    ("use std::cmp::Ordering;", ["Ordering"]),
    ("use std::collections::{BTreeMap, BTreeSet};", ["BTreeMap", "BTreeSet"]),
    ("use std::fmt;", ["fmt"]),
    ("use std::io::Read;", ["read_to_end", "read_to_string", "read_exact", ".take(", "Read"]),
    ("use std::str::FromStr;", ["FromStr", "from_str", ".parse::<"]),
    ("use schemars::JsonSchema;", ["JsonSchema"]),
    ("use serde::{Deserialize, Deserializer, Serialize, Serializer};", ["Deserialize", "Deserializer", "Serialize", "Serializer"]),
    ("use sha2::{Digest, Sha256};", ["Sha256", "Digest"]),
    ("use crate::identity::string_json_schema;", ["string_json_schema"]),
    ("use crate::release_observation::{ProviderEvidenceV1, ProviderObservationError, ProviderObservationV1, ReleaseOperationObservationV1};",
     ["ProviderEvidenceV1", "ProviderObservationError", "ProviderObservationV1", "ReleaseOperationObservationV1"]),
    ("use crate::release_transition::OperationEvent;", ["OperationEvent"]),
    ("use crate::{CommitSha, Ecosystem, PackageId, RegistryKey, Version, VersionGrammar};",
     ["CommitSha", "Ecosystem", "PackageId", "RegistryKey", "Version", "VersionGrammar"]),
]

def external_imports(body):
    stripped = strip_comments(body)
    out = {}
    for line, idents in EXT:
        names = re.findall(r"[A-Za-z_][A-Za-z_0-9]*", line.split("::", 1)[1] if "::" in line else line)
        # keep only the idents of this line actually used
        if line.startswith("use std::io::Read"):
            if any(x in stripped for x in ["read_to_end", "read_to_string", "read_exact", ".take(", ".read("]):
                out[line] = line
            continue
        if line.startswith("use sha2"):
            parts = []
            if "Sha256" in stripped:
                parts += ["Digest", "Sha256"]
            if parts:
                out[line] = "use sha2::{Digest, Sha256};"
            continue
        used = [i for i in idents if uses(stripped, i)]
        if not used:
            continue
        m = re.match(r"use (.+)::\{(.+)\};", line)
        if m:
            sel = [i for i in [x.strip() for x in m.group(2).split(",")] if i in used]
            out[line] = f"use {m.group(1)}::{{{', '.join(sel)}}};" if len(sel) > 1 else f"use {m.group(1)}::{sel[0]};"
        else:
            out[line] = line
    return list(out.values())

for m in MODS:
    body = text[m]
    stripped = strip_comments(body)
    ext = external_imports(body)
    pub_sib, priv_sib = {}, {}
    for name, (mod, is_pub) in defs.items():
        if mod == m:
            continue
        if re.search(rf"\b{re.escape(name)}\b", stripped):
            if mod == "":
                pub_sib.setdefault("super", []).append(name)
            elif is_pub:
