import re, pathlib

D = pathlib.Path("crates/callisto-model/src/release")

SPECS = [
    ("ReleasePackageId", "package_id.rs", "String", "ReleasePackageIdParseError", "raw", "Self::parse(&raw)"),
    ("GitHubRepository", "github.rs", "String", "GitHubRepositoryParseError", "raw", "Self::parse(&raw)"),
    ("RegistryBindingId", "operation.rs", "RegistryBindingIdWire", "ReleaseOperationError", "wire",
     "Self::new(wire.registry_key, wire.binding_digest)"),
    ("PlatformPackageV1", "operation.rs", "PlatformPackageV1Wire", "ReleaseOperationError", "wire",
     "Self::new(wire.name, wire.directory)"),
    ("GitHubAttestationPolicyV1", "github.rs", "GitHubAttestationPolicyV1Wire", "ArtifactSlotError", "wire",
     "Self::new(wire.repository, wire.workflow_path, wire.workflow_commit)"),
    ("ReleaseIntentV1", "intent.rs", "ReleaseIntentV1Wire", "ReleaseIntentError", "wire", "Self::from_wire(wire)"),
    ("ReleaseReceiptV1", "execution.rs", "ReleaseReceiptV1Wire", "ReleaseReceiptError", "wire", "Self::from_wire(wire)"),
    ("ReleaseDecisionEntry", "decision.rs", "ReleaseDecisionEntryWire", "VersionParseError", "wire",
     """let target_version = Version::parse_for_ecosystem(&wire.target_version, wire.package.ecosystem())?;
        Ok(Self {
            package: wire.package,
            target_version,
            reasons: wire.reasons,
        })"""),
    ("ReleaseRunEnvelopeV1", "execution.rs", "ReleaseRunEnvelopeV1Wire", "ReleaseRunEnvelopeError", "wire",
     """if wire.schema_version != ReleaseRunEnvelopeV1::SCHEMA_VERSION {
            return Err(ReleaseRunEnvelopeError::UnsupportedSchema {
                found: wire.schema_version,
            });
        }
        Ok(Self {
            schema_version: wire.schema_version,
            orchestration_revision: wire.orchestration_revision,
            release_source_revision: wire.release_source_revision,
            intent_digest: wire.intent_digest,
            artifact_manifest_digest: wire.artifact_manifest_digest,
        })"""),
    ("ReleaseOperationRole", "operation.rs", "ReleaseOperationRoleWire", "ReleaseOperationError", "wire",
     """Ok(match wire {
            ReleaseOperationRoleWire::RegistryPublish {
                registry_key,
                binding_digest,
            } => Self::RegistryPublish {
                registry: RegistryBindingId::new(registry_key, binding_digest)?,
            },
            ReleaseOperationRoleWire::Tag => Self::Tag,
            ReleaseOperationRoleWire::ForgeRelease => Self::ForgeRelease,
            ReleaseOperationRoleWire::ArtifactUpload { slot } => Self::ArtifactUpload { slot },
            ReleaseOperationRoleWire::ForgePublish => Self::ForgePublish,
            ReleaseOperationRoleWire::PlatformPublish {
                registry_key,
                binding_digest,
                platform,
            } => Self::PlatformPublish {
                registry: RegistryBindingId::new(registry_key, binding_digest)?,
                platform,
            },
        })"""),
]

for ty, fname, src, err, param, body in SPECS:
    p = D / fname
    t = p.read_text()

    # 1. replace the hand-written Deserialize impl
    pat = re.compile(rf"impl<'de> Deserialize<'de> for {ty} \{{.*?^\}}\n", re.S | re.M)
    assert pat.search(t), ty
    indent = "        " if "\n" in body else ""
    body_txt = body if "\n" in body else body
    impl = (f"impl TryFrom<{src}> for {ty} {{\n    type Error = {err};\n\n"
            f"    fn try_from({param}: {src}) -> Result<Self, Self::Error> {{\n        {body_txt}\n    }}\n}}\n")
    t = pat.sub(impl.replace("\\", "\\\\"), t, count=1)

    # 2. derive Deserialize on the public type and point serde at the conversion source
    head = re.compile(rf"((?:^#\[[^\n]*\]\n)+)(pub (?:struct|enum) {ty}\b)", re.M)
    m = head.search(t)
    assert m, ty
    attrs = m.group(1)
    if re.search(r"#\[derive\([^)]*Serialize", attrs):
        attrs = re.sub(r"(#\[derive\([^)]*Serialize)", r"\1, Deserialize", attrs, count=1)
    else:
        attrs = re.sub(r"(#\[derive\([^)]*\)\]\n)", r"\1#[derive(Deserialize)]\n", attrs, count=1)
    if "#[serde(" in attrs:
        attrs = attrs.replace("#[serde(", f'#[serde(try_from = "{src}", ', 1)
    else:
        attrs += f'#[serde(try_from = "{src}")]\n'
    t = t[: m.start()] + attrs + m.group(2) + t[m.end():]
    p.write_text(t)
    print("ok", ty)

