    "crates/callisto-model/src/tag.rs": [("TagTemplate", "parse"), ("TagName", "parse")],
}
for f, items in T.items():
    t = open(f).read()
    for ty, fn in items:
        sig = None
        for m in re.finditer(rf"^impl {ty} \{{(.*?)^\}}", t, re.S | re.M):
